"use client";

import React, { useEffect } from "react";
import { motion, useScroll, useTransform } from "framer-motion";
import { UnicornScene } from "unicornstudio-react";
import { Navigation } from "@/components/Navigation";

export function LandingView({ onEnterAegis }: { onEnterAegis: () => void }) {
    const { scrollY } = useScroll();
    const yText = useTransform(scrollY, [0, 1000], [0, -400]);

    // Remove Unicorn Studio watermark from DOM
    useEffect(() => {
        const removeWatermark = () => {
            document.querySelectorAll('a[href*="unicorn.studio"]').forEach(node => node.remove());
        };
        const interval = setInterval(removeWatermark, 500);
        setTimeout(() => clearInterval(interval), 5000);

        return () => clearInterval(interval);
    }, []);

    return (
        <div className="relative w-full text-white min-h-screen">
            {/* Shared Navigation — no Launch Console button */}
            <Navigation />

            {/* Background - Unicorn Studio (Only in Hero) */}
            <div
                className="fixed top-0 left-0 w-full h-[100vh] pointer-events-none"
                style={{
                    zIndex: 0,
                    maskImage: "linear-gradient(to bottom, black 70%, transparent 100%)",
                    WebkitMaskImage: "linear-gradient(to bottom, black 70%, transparent 100%)"
                }}
            >
                <UnicornScene
                    projectId="ye7FVUbWpTAYh806M04d"
                    // @ts-ignore
                    width="100%"
                    height="100vh"
                />
            </div>

            {/* Hero Section */}
            <section className="h-screen flex flex-col items-center justify-center w-full relative z-10 pt-20">
                <motion.div
                    style={{ y: yText }}
                    initial={{ opacity: 0, scale: 0.95 }}
                    animate={{ opacity: 1, scale: 1 }}
                    transition={{ duration: 0.8, ease: "easeOut" }}
                    className="flex flex-col items-center"
                >
                    <h1 className="text-7xl md:text-9xl font-extrabold tracking-tighter text-gradient mb-8 drop-shadow-2xl relative">
                        <div className="absolute -top-4 left-1/4 right-1/4 h-[1px] bg-gradient-to-r from-transparent via-[#E0B0FF]/50 to-transparent blur-[2px]"></div>
                        AEGIS SRE
                    </h1>
                    <p className="text-xl md:text-2xl text-gray-300 max-w-2xl text-center mb-12 font-medium tracking-wide">
                        Enterprise Reliability Command System
                    </p>

                    <motion.button
                        onClick={onEnterAegis}
                        whileHover={{ scale: 1.02 }}
                        whileTap={{ scale: 0.98 }}
                        className="px-10 py-4 rounded-full glass-panel border border-[#E0B0FF]/20 text-lg font-semibold tracking-wider transition-all hover:bg-white/10 hover:shadow-[0_0_20px_rgba(224,176,255,0.2)]"
                    >
                        Initialize Agent
                    </motion.button>
                </motion.div>
            </section>

            {/* Hero -> Content Transition Bar */}
            <div
                className="w-full h-[120px] relative z-10"
                style={{
                    background: "linear-gradient(to bottom, rgba(15,17,23,0) 0%, rgba(15,17,23,0.6) 40%, #0F1117 100%)",
                    borderTop: "1px solid rgba(255,255,255,0.06)"
                }}
            />

            {/* Content Sections — anti-box: asymmetrical wide bands, no uniform card grid */}
            <div className="relative z-10 bg-[#0F1117] w-full min-h-screen">
                {/* Grain texture continuity */}
                <div
                    className="absolute inset-0 opacity-[0.015] pointer-events-none mix-blend-overlay"
                    style={{
                        backgroundImage: "url('data:image/svg+xml;utf8,<svg viewBox=%220 0 256 256%22 xmlns=%22http://www.w3.org/2000/svg%22><filter id=%22n%22><feTurbulence type=%22fractalNoise%22 baseFrequency=%220.85%22 numOctaves=%224%22 stitchTiles=%22stitch%22/></filter><rect width=%22100%25%22 height=%22100%25%22 filter=%22url(%23n)%22/></svg>')",
                    }}
                />

                <div className="max-w-6xl mx-auto px-6 py-24 relative z-10">
                    {/* Staggered vertical stack — not a grid */}
                    <div className="flex flex-col gap-16">
                        {/* Section 1 — full width band */}
                        <motion.div
                            initial={{ opacity: 0, y: 30 }}
                            whileInView={{ opacity: 1, y: 0 }}
                            viewport={{ once: true, margin: "-50px" }}
                            transition={{ duration: 0.7 }}
                            className="w-full rounded-[2rem] p-10 lg:p-14 relative overflow-hidden"
                            style={{
                                background: "linear-gradient(135deg, rgba(74,14,96,0.08) 0%, rgba(15,17,23,0.5) 50%, rgba(5,5,5,0.3) 100%)",
                                backdropFilter: "blur(12px)",
                            }}
                        >
                            <div className="absolute top-0 inset-x-0 h-px bg-gradient-to-r from-transparent via-[#E0B0FF]/15 to-transparent" />
                            <div className="flex flex-col lg:flex-row lg:items-center gap-8">
                                <div className="flex-1">
                                    <div className="text-xs font-mono uppercase tracking-[0.3em] text-[#E0B0FF]/50 mb-4">Observe</div>
                                    <h2 className="text-2xl md:text-3xl font-bold text-white mb-3 tracking-tight">Real-Time Telemetry</h2>
                                    <p className="text-gray-400 leading-relaxed max-w-lg">
                                        Monitor telemetry, traces, and critical metrics across the entire architectural stack with sub-second precision.
                                    </p>
                                </div>
                                <div className="shrink-0 text-right">
                                    <span className="text-xs font-mono uppercase tracking-wider text-[#E0B0FF]/80 block">99.999% SLA Uptime</span>
                                </div>
                            </div>
                        </motion.div>

                        {/* Section 2 — two-column split, uneven */}
                        <div className="grid grid-cols-1 lg:grid-cols-12 gap-6">
                            <motion.div
                                initial={{ opacity: 0, y: 30 }}
                                whileInView={{ opacity: 1, y: 0 }}
                                viewport={{ once: true, margin: "-50px" }}
                                transition={{ duration: 0.7, delay: 0.1 }}
                                className="lg:col-span-7 rounded-[2rem] p-10 lg:p-14 relative overflow-hidden"
                                style={{
                                    background: "linear-gradient(160deg, rgba(74,14,96,0.1) 0%, rgba(15,17,23,0.6) 60%, rgba(5,5,5,0.4) 100%)",
                                    backdropFilter: "blur(16px)",
                                }}
                            >
                                <div className="absolute top-0 inset-x-0 h-px bg-gradient-to-r from-transparent via-[#E0B0FF]/12 to-transparent" />
                                <div className="text-xs font-mono uppercase tracking-[0.3em] text-[#E0B0FF]/50 mb-4">Reason</div>
                                <h2 className="text-2xl md:text-3xl font-bold text-white mb-3 tracking-tight">LLM-Powered Root Cause Analysis</h2>
                                <p className="text-gray-400 leading-relaxed max-w-lg">
                                    Automate root cause analysis with LLM-powered insights, correlating spikes and anomalies instantaneously.
                                </p>
                                <div className="mt-6">
                                    <span className="text-xs font-mono uppercase tracking-wider text-[#E0B0FF]/80">&lt; 200ms Inference</span>
                                </div>
                            </motion.div>

                            <motion.div
                                initial={{ opacity: 0, y: 30 }}
                                whileInView={{ opacity: 1, y: 0 }}
                                viewport={{ once: true, margin: "-50px" }}
                                transition={{ duration: 0.7, delay: 0.2 }}
                                className="lg:col-span-5 rounded-[2rem] p-10 relative overflow-hidden flex flex-col justify-center"
                                style={{
                                    background: "linear-gradient(145deg, rgba(224,176,255,0.04) 0%, rgba(15,17,23,0.5) 100%)",
                                    backdropFilter: "blur(12px)",
                                }}
                            >
                                <div className="absolute bottom-0 inset-x-0 h-px bg-gradient-to-r from-transparent via-white/5 to-transparent" />
                                <div className="text-xs font-mono uppercase tracking-[0.3em] text-[#E0B0FF]/50 mb-4">Act</div>
                                <h2 className="text-2xl font-bold text-white mb-3 tracking-tight">Autonomous Remediation</h2>
                                <p className="text-gray-400 leading-relaxed">
                                    Execute remediation workflows, scale infrastructure, or rollback deployments seamlessly.
                                </p>
                                <div className="mt-6">
                                    <span className="text-xs font-mono uppercase tracking-wider text-[#E0B0FF]/80">0 Human Interventions</span>
                                </div>
                            </motion.div>
                        </div>
                    </div>
                </div>
            </div>
        </div>
    );
}
